import{_ as t,c as a,o as s,a5 as n}from"./chunks/framework.CgT1UzWm.js";const u=JSON.parse('{"title":"Changelog v4.0.1","description":"NpgsqlRest v4.0.1: patch release. Fixes a 4.0.0 regression (password login failed with 404 on endpoints that use user parameters), JWT role checks and claim names, logout with a JWT, typed defaults of SQL file parameters, and three TypeScript client typing bugs.","frontmatter":{"description":"NpgsqlRest v4.0.1: patch release. Fixes a 4.0.0 regression (password login failed with 404 on endpoints that use user parameters), JWT role checks and claim names, logout with a JWT, typed defaults of SQL file parameters, and three TypeScript client typing bugs.","head":[["link",{"rel":"canonical","href":"https://npgsqlrest.github.io/guide/changelog/v4.0.1.html"}],["meta",{"property":"og:url","content":"https://npgsqlrest.github.io/guide/changelog/v4.0.1.html"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Changelog v4.0.1"}],["meta",{"property":"og:description","content":"NpgsqlRest v4.0.1: patch release. Fixes a 4.0.0 regression (password login failed with 404 on endpoints that use user parameters), JWT role checks and claim names, logout with a JWT, typed defaults of SQL file parameters, and three TypeScript client typing bugs."}],["meta",{"property":"og:image","content":"https://npgsqlrest.github.io/og-image.png"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Changelog v4.0.1"}],["meta",{"name":"twitter:description","content":"NpgsqlRest v4.0.1: patch release. Fixes a 4.0.0 regression (password login failed with 404 on endpoints that use user parameters), JWT role checks and claim names, logout with a JWT, typed defaults of SQL file parameters, and three TypeScript client typing bugs."}],["meta",{"name":"twitter:image","content":"https://npgsqlrest.github.io/og-image.png"}]]},"headers":[],"relativePath":"guide/changelog/v4.0.1.md","filePath":"guide/changelog/v4.0.1.md","lastUpdated":1794206981000}'),i={name:"guide/changelog/v4.0.1.md"};function o(r,e,d,l,h,c){return s(),a("div",null,e[0]||(e[0]=[n('<h1 id="changelog-v4-0-1" tabindex="-1">Changelog v4.0.1 <a class="header-anchor" href="#changelog-v4-0-1" aria-label="Permalink to &quot;Changelog v4.0.1&quot;">​</a></h1><h2 id="version-4-0-1-2026-11-20" tabindex="-1">Version <a href="https://github.com/NpgsqlRest/NpgsqlRest/tree/4.0.1" target="_blank" rel="noreferrer">4.0.1</a> (2026-11-20) <a class="header-anchor" href="#version-4-0-1-2026-11-20" aria-label="Permalink to &quot;Version [4.0.1](https://github.com/NpgsqlRest/NpgsqlRest/tree/4.0.1) (2026-11-20)&quot;">​</a></h2><p><a href="https://github.com/NpgsqlRest/NpgsqlRest/compare/4.0.0...4.0.1" target="_blank" rel="noreferrer">Full Changelog</a></p><p>Patch release. It fixes one regression of 4.0.0 (<strong>password login failed on endpoints that use user parameters</strong>), one problem that 4.0.0 made visible (<strong>role checks failed for JWT sign-ins</strong>), and five older bugs. All of them were found by upgrading the <a href="https://github.com/NpgsqlRest/npgsqlrest-docs/tree/main/examples" target="_blank" rel="noreferrer">examples</a> to 4.0.0 and running every one of them. No configuration key was added, removed or renamed.</p><p><strong>Who should upgrade:</strong> everyone on 4.0.0 who uses <code>UseUserParameters</code> (or <code>user_params</code>) together with a <code>login</code> endpoint, or who signs users in with JWT and uses roles.</p><h3 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><h4 id="login-failed-404-when-the-login-parameter-had-a-claim-mapped-name" tabindex="-1">Login failed (404) when the login parameter had a claim-mapped name <a class="header-anchor" href="#login-failed-404-when-the-login-parameter-had-a-claim-mapped-name" aria-label="Permalink to &quot;Login failed (404) when the login parameter had a claim-mapped name&quot;">​</a></h4><p><strong>A regression in 4.0.0.</strong> Applies to <code>login</code> endpoints on which user parameters are enabled (<code>UseUserParameters: true</code>, or the <code>user_params</code> annotation) and whose routine has a parameter with a name from <code>ParameterNameClaimsMapping</code>: by default <code>_user_id</code>, <code>_user_name</code> and <code>_user_roles</code>, and very often a mapped <code>_username</code>.</p><p><strong>What was wrong.</strong> 4.0.0 stopped anonymous callers from sending values for claim-mapped parameters (<a href="/guide/changelog/v4.0.0.html#breaking-anonymous-callers-can-no-longer-fill-user-parameters-user-params">4.0.0: anonymous callers can no longer fill user parameters</a>). A login request is anonymous by definition, and its parameters are the credentials. So with this configuration, which is the one the authentication guide shows:</p><details class="code-collapsible" open><summary>jsonc</summary><div class="language-jsonc vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">&quot;AuthenticationOptions&quot;</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">: </span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">{</span></span>\n<span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">  &quot;</span><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">UseUserParameters</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">:</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> true</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">,</span></span>\n<span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">  &quot;</span><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">ParameterNameClaimsMapping</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">:</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> {</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> &quot;</span><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">_user_id</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">:</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> &quot;user_id&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">,</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> &quot;</span><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">_username</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">:</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> &quot;username&quot;</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> }</span></span>\n<span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div></details><details class="code-collapsible" open><summary>sql</summary><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">create</span><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;"> function</span><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> login</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">(_username </span><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">text</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">, _password </span><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">text</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">) </span><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">returns</span><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;"> table</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;"> (...) ...;</span></span>\n<span class="line"><span style="--shiki-light:#8839EF;--shiki-dark:#CBA6F7;">comment on function login(text, text) is </span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">&#39;HTTP POST</span></span>\n<span class="line"><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">login&#39;</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></details><p>the submitted <code>username</code> was removed from the request, the routine no longer matched, and every login answered <code>404</code> with nothing in the log. No one could sign in.</p><p><strong>What changed.</strong> Request values for claim-mapped parameters are kept on <code>login</code> endpoints. Everywhere else the 4.0.0 rule stands: an anonymous caller cannot fill them.</p><p><strong>Workaround on 4.0.0.</strong> Turn <code>UseUserParameters</code> off and put the <code>user_params</code> annotation on the endpoints that need the claims, or rename the login parameter.</p><h4 id="jwt-authorize-role-answered-403-and-roles-and-email-were-null" tabindex="-1">JWT: <code>authorize role</code> answered 403, and roles and email were NULL <a class="header-anchor" href="#jwt-authorize-role-answered-403-and-roles-and-email-were-null" aria-label="Permalink to &quot;JWT: `authorize role` answered 403, and roles and email were NULL&quot;">​</a></h4><p>Applies to JWT sign-ins (<code>Auth:JwtAuth</code>, or an <code>Auth:Schemes</code> entry of type <code>Jwt</code>) where the role claim is named <code>roles</code> or <code>role</code>, or where a claim is named <code>email</code>, <code>sub</code> or another name the JWT handler knows.</p><p><strong>What was wrong.</strong> The JWT bearer handler renames well-known claim types when it reads a token: <code>roles</code> and <code>role</code> become <code>http://schemas.microsoft.com/ws/2008/06/identity/claims/role</code>, <code>email</code> becomes <code>.../claims/emailaddress</code>, and so on. After a JWT sign-in the claims therefore no longer had the names the login routine returned. With <code>DefaultRoleClaimType: &quot;roles&quot;</code>:</p><ul><li><code>authorize admin</code> did not find the role claim. Before 4.0.0 a plain <code>authorize</code> value also matched the user name and the user id, so a user named like the role was let in by accident and the others got <code>403</code>. Since 4.0.0 a plain value is a role only, so <strong>every</strong> JWT user got <code>403</code> on an endpoint with <code>authorize &lt;role&gt;</code>.</li><li>the role and email claims were NULL in user parameters and in the user context (<code>request.roles</code>, <code>request.email</code>).</li><li>a refreshed token carried the renamed claims, so the claim names changed again after the first refresh.</li></ul><p>Cookie and bearer-token sign-ins were never affected.</p><p><strong>What changed.</strong> The client registers JWT schemes with <code>MapInboundClaims = false</code>, and validates refresh tokens the same way. Claims of a JWT sign-in keep the names the login routine gave them, as they do for cookies. Tokens issued by 4.0.0 stay valid. One case needs a new sign-in: a token that an earlier version issued <strong>from a refresh token</strong> already contains the renamed claims, and they are now read as they are written, so such a user has no <code>roles</code> claim until they sign in again.</p><p><strong>What to check.</strong> If your code works around this by reading the long claim names (for example <code>DefaultRoleClaimType</code> set to the <code>http://schemas.microsoft.com/...</code> URI), change it back to the short name used in the login routine.</p><h4 id="logout-with-a-jwt-answered-500" tabindex="-1">Logout with a JWT answered 500 <a class="header-anchor" href="#logout-with-a-jwt-answered-500" aria-label="Permalink to &quot;Logout with a JWT answered 500&quot;">​</a></h4><p><strong>What was wrong.</strong> A <code>logout</code> endpoint called with a JWT, or a logout routine that returns the name of a JWT scheme, failed with &quot;The authentication handler registered for scheme &#39;jwt&#39; is &#39;JwtBearerHandler&#39; which cannot be used for SignOutAsync&quot; and answered <code>500</code>.</p><p><strong>What changed.</strong> A scheme whose handler cannot sign out is skipped. A JWT scheme keeps no session on the server: the client discards its tokens. Cookie and bearer-token schemes named in the same logout are signed out as before, and an unknown scheme name is still reported.</p><h4 id="sql-files-a-typed-parameter-with-a-default-failed-500-when-the-request-left-it-out" tabindex="-1">SQL files: a typed parameter with a default failed (500) when the request left it out <a class="header-anchor" href="#sql-files-a-typed-parameter-with-a-default-failed-500-when-the-request-left-it-out" aria-label="Permalink to &quot;SQL files: a typed parameter with a default failed (500) when the request left it out&quot;">​</a></h4><p><strong>What was wrong.</strong> For a parameter with a type and a default:</p><details class="code-collapsible" open><summary>sql</summary><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">-- @param $1 productId int</span></span>\n<span class="line"><span style="--shiki-light:#9CA0B0;--shiki-light-font-style:italic;--shiki-dark:#6C7086;--shiki-dark-font-style:italic;">-- @param $2 quantity int default 1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></details><p>a request without <code>quantity</code> failed with <code>500</code> (&quot;Writing values of &#39;System.String&#39; is not supported for parameters having NpgsqlDbType &#39;Integer&#39;&quot;). The default is written as text in the annotation, and it was bound as text. Defaults of parameters without a declared type, and <code>default null</code>, worked.</p><p><strong>What changed.</strong> The default is converted to the parameter&#39;s type, exactly as a value from the query string is. This applies to query string and JSON body parameters, and to the <code>= value</code> form.</p><h4 id="typescript-client-defaultjsontype-was-string-when-it-was-not-set" tabindex="-1">TypeScript client: <code>DefaultJsonType</code> was <code>string</code> when it was not set <a class="header-anchor" href="#typescript-client-defaultjsontype-was-string-when-it-was-not-set" aria-label="Permalink to &quot;TypeScript client: `DefaultJsonType` was `string` when it was not set&quot;">​</a></h4><p><strong>What was wrong.</strong> <code>ClientCodeGen:DefaultJsonType</code> is documented with the default <code>any</code>, and that is the default of the plugin option. The <code>npgsqlrest</code> client used <code>string</code> when the key was missing from the configuration. JSON values typed from this setting (results of multi-command SQL files, fields of composite types) were then declared as <code>string</code> although the response contains JSON.</p><p><strong>What changed.</strong> The default is <code>any</code>, as documented. To keep the earlier output, set <code>&quot;DefaultJsonType&quot;: &quot;string&quot;</code>.</p><h4 id="typescript-client-void-on-a-multi-command-sql-file" tabindex="-1">TypeScript client: <code>void</code> on a multi-command SQL file <a class="header-anchor" href="#typescript-client-void-on-a-multi-command-sql-file" aria-label="Permalink to &quot;TypeScript client: `void` on a multi-command SQL file&quot;">​</a></h4><p><strong>What was wrong.</strong> A multi-command SQL file with the <code>void</code> annotation answers <code>204</code> with no body. Its client function was still declared as returning the command results and read them with <code>response.json()</code>, which throws &quot;Unexpected end of JSON input&quot; in the browser.</p><p><strong>What changed.</strong> The function returns <code>void</code> (or the status object when status codes are included), and no response interface is generated for it.</p><h4 id="typescript-client-return-type-of-a-pass-through-proxy-function" tabindex="-1">TypeScript client: return type of a pass-through proxy function <a class="header-anchor" href="#typescript-client-return-type-of-a-pass-through-proxy-function" aria-label="Permalink to &quot;TypeScript client: return type of a pass-through proxy function&quot;">​</a></h4><p><strong>What was wrong.</strong> For a pass-through proxy (a <code>proxy</code> endpoint on a routine that returns void) and for <code>proxy_out</code>, the client function returns the <code>fetch</code> response itself. With status codes included, which is the default of the <code>npgsqlrest</code> client, it was declared as <code>Promise&lt;ApiResult&lt;Response&gt;&gt;</code>, so <code>result.response</code> and <code>result.error</code> type-checked and were <code>undefined</code> at run time, and the generated file did not compile in strict mode.</p><p><strong>What changed.</strong> The function is declared as <code>Promise&lt;Response&gt;</code>. Code that read <code>.status</code> from the result is unaffected; code that read <code>.response</code> or <code>.error</code> now gets a compile error where it used to get <code>undefined</code>.</p><h4 id="timeout-messages-depended-on-the-regional-settings-of-the-server" tabindex="-1">Timeout messages depended on the regional settings of the server <a class="header-anchor" href="#timeout-messages-depended-on-the-regional-settings-of-the-server" aria-label="Permalink to &quot;Timeout messages depended on the regional settings of the server&quot;">​</a></h4><p>The error message of a timed-out HTTP Custom Type call, proxy call or <code>proxy_out</code> call contained the timeout formatted with the server&#39;s culture: <code>Request timed out after 0,3 seconds</code> on a system with a decimal comma. The message is data handed to the routine, so it is now always <code>0.3 seconds</code>.</p><h3 id="known-issue-not-fixed-in-this-release" tabindex="-1">Known issue, not fixed in this release <a class="header-anchor" href="#known-issue-not-fixed-in-this-release" aria-label="Permalink to &quot;Known issue, not fixed in this release&quot;">​</a></h3><p>When a statement of a multi-command SQL file fails after an earlier statement has written output, the error body is not valid JSON (the problem details follow the partial output). The status code is correct. This is not new in 4.0.0; earlier versions appended the partial output after the problem details.</p><h3 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h3><ul><li><code>UserParamsTests.Test_login_keeps_claim_mapped_credential_parameters</code>: a <code>login</code> routine with a claim-mapped <code>_user_name</code> parameter and <code>user_params</code> signs in, and rejects a wrong secret.</li><li><code>JwtClaimNamesTests</code>: the claims of an access token, and of a token issued from a refresh token, keep the names <code>roles</code>, <code>email</code>, <code>username</code> and <code>user_id</code>.</li><li><code>AuthSchemeLoginTests.Logout_naming_a_jwt_scheme_succeeds_and_still_signs_out_the_cookie_scheme</code>.</li><li><code>ParamDefaultValueTests</code>: typed defaults (<code>int</code>, <code>numeric</code>, <code>boolean</code>, <code>date</code>) left out and supplied, in the query string and in the JSON body.</li><li><code>TsClientDefaultJsonTypeTests</code>: the client fallback, the plugin option default and the documented default agree.</li><li><code>SqlFileTsClientTests.TsClient_MultiCommand_VoidAnnotation_ReturnsVoid</code> and <code>ProxyPassthroughResponseTests.Test_ProxyPassthroughResponse_WithStatusCode_StillReturnsResponse</code>.</li><li>The timeout message is covered by the existing <code>HttpClientTypeFixesTests.Call_to_an_own_endpoint_honors_the_timeout</code>, which failed on a system with a decimal comma.</li></ul><p>Full suite green on .NET 11 (3298) and .NET 10 (3279).</p><h3 id="nuget-package-upgrades" tabindex="-1">NuGet Package Upgrades <a class="header-anchor" href="#nuget-package-upgrades" aria-label="Permalink to &quot;NuGet Package Upgrades&quot;">​</a></h3><div class="table-container"><div class="table-wrapper"><table tabindex="0"><thead><tr><th>Package</th><th>Version</th></tr></thead><tbody><tr><td><code>NpgsqlRest</code></td><td>4.0.0 → 4.0.1</td></tr><tr><td><code>NpgsqlRest.TsClient</code></td><td>1.38.0 → 1.38.1</td></tr></tbody></table></div></div><p>The other plugins are unchanged.</p>',48)]))}const g=t(i,[["render",o]]);export{u as __pageData,g as default};
